import{_ as t,o as n,c as r,ag as s}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学日报 | 2026年8月27日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-08-27.md","filePath":"science-log/src/science-daily/2026-08-27.md"}'),g={name:"science-log/src/science-daily/2026-08-27.md"};function e(a,o,u,q,i,c){return n(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="🔬-科学日报-2026年8月27日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年8月27日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年8月27日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年8月27日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：<strong>事后重建版简讯</strong>（science-log/src/reconstructed/2026-08-27.md，共 10 条：科学前沿 5 + AI 前沿 5；科学取自 Science / PNAS 当日研究论文，AI 取自当日 arXiv cs.AI 提交） 分析日期：2026-08-27 版本：扩展版（10 条深度 + 交叉关联） ⚠️ 本日简讯为<strong>事后重建版</strong>（2026-11-05 按 arXiv/CrossRef 日期回溯生成，非当日发布原文，不代表历史原貌）</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-用深度学习从头设计-rna-假结-生成式-ai-在盲测中追平人类专家" tabindex="-1">1. 用深度学习从头设计 RNA 假结：生成式 AI 在盲测中追平人类专家 <a class="header-anchor" href="#_1-用深度学习从头设计-rna-假结-生成式-ai-在盲测中追平人类专家" aria-label="Permalink to &quot;1. 用深度学习从头设计 RNA 假结：生成式 AI 在盲测中追平人类专家&quot;">​</a></h3><p><strong>原文</strong>：RNA 设计长期受限于三维结构预测精度；本文转向假结（pseudoknot）二级结构这一足够复杂、又可用现有工具可靠判定的目标，证明复杂 RNA 结构可以被从头设计出来。</p><p><strong>深度扩展</strong>：</p><p>这项工作发表于 <strong>Science（2026，第 6814 期）</strong>，由 <strong>27 位作者</strong>合作完成（作者名单含蛋白设计领域知名的 <strong>David Baker</strong>，以及长期经营 RNA 设计平台的 <strong>Kladwang / Das</strong> 一线团队——前者来自华盛顿大学、后者来自斯坦福，但机构归属未在本次取证的元数据中逐条确认，此处仅按作者身份标注）。它要解决的问题很具体：<strong>RNA 纳米结构与 RNA 药物的&quot;设计—构建—测试&quot;闭环一直跑不起来</strong>，根本原因是分子三维结构预测精度不够，设计者无法预判自己写下的序列会折成什么。</p><p>作者的办法是<strong>绕开三维预测</strong>，把目标降到<strong>假结二级结构</strong>——这是一类由茎区交叉堆叠形成的复杂拓扑，足够难，却可以被现有算法较可靠地判定。在 <strong>Eterna</strong> 平台上组织的竞赛里，<strong>57 个假结</strong>被作为盲题交给生成式 AI 与人类高手同台求解；评价不用&quot;看起来合理&quot;，而用<strong>单核苷酸分辨率的化学映射</strong>（读出每个位点是配对还是柔性）、<strong>补偿性突变</strong>（破坏配对再配对回来，看表型是否随之恢复）以及<strong>冷冻电镜</strong>三层硬证据。</p><p>结果是：<strong>AI 方法在多数盲题上与有经验的人类设计者打成平手</strong>，而且 AI 生成的分子不只是二级结构正确——它们折叠成<strong>良好有序的三维构象</strong>，其稳定还依赖于<strong>建模时并未显式指定的非经典三级相互作用</strong>。这既说明&quot;设计二级结构&quot;是一条可行的降维路线，也说明这类分子的三维行为<strong>超出了设计模型的显式控制范围</strong>，给后续实验筛选留下了必要位置。</p><p><strong>跨主题关联</strong>：这条把&quot;<strong>生成式模型 + 实验闭环</strong>&quot;做成了 RNA 版，与 <code>topics/biomedicine/index.md</code> 中 RNA 药物 / 递送系统的脉络直接接续；其方法论（<strong>先设计可判定的低维表示，再用实验回填高维真实</strong>）与 <code>topics/ai-brain/index.md</code> 主张的&quot;先让信息可表示、可观测，再谈聚合&quot;是同一条路线。</p><hr><h3 id="_2-trace-不依赖参考基因组与外来群-从祖先重组图中捞出-幽灵-古人类血缘" tabindex="-1">2. TRACE：不依赖参考基因组与外来群，从祖先重组图中捞出&quot;幽灵&quot;古人类血缘 <a class="header-anchor" href="#_2-trace-不依赖参考基因组与外来群-从祖先重组图中捞出-幽灵-古人类血缘" aria-label="Permalink to &quot;2. TRACE：不依赖参考基因组与外来群，从祖先重组图中捞出&quot;幽灵&quot;古人类血缘&quot;">​</a></h3><p><strong>原文</strong>：现代人基因组留有已灭绝古人类的混血印记，但重建这段历史受制于古样本稀少、缺少&quot;未混合&quot;外来群；TRACE 既不需要参考基因组也不需要外来群，改用祖先重组图（ARG）的结构特征识别古人类血缘。</p><p><strong>深度扩展</strong>：</p><p><strong>Science（2026）</strong>，作者为 <strong>Zhang Yulin、Biddanda Arjun、Johnson Sarah A.、O&#39;Dushlaine Colm、Moorjani Priya</strong> 共 <strong>5 人</strong>。混血检测是古人类遗传学的核心难题，而既往方法的<strong>两个依赖</strong>长期卡着这条路：一是要有<strong>足够的古样本</strong>（化石中能提 DNA 的极少），二是要有**&quot;未混合&quot;的外来群**（用于判断某段序列&quot;不属于现代人&quot;）——非洲人群中恰恰缺乏这样的外来群，因此非洲人的古人类混血一直最难判定。</p><p><strong>TRACE</strong> 把注意力从&quot;比对序列&quot;转到&quot;<strong>读谱系结构</strong>&quot;：<strong>祖先重组图（ARG）<strong>编码了每个基因组位点的</strong>谱系拓扑与重组断点</strong>，混血引入的外来片段会在 ARG 上留下可识别的结构特征——不需要参考样本，也不需要外来群。作者先做<strong>模拟</strong>验证：TRACE 具备<strong>高精度与低假发现率</strong>。</p><p>随后把 TRACE 用于 <strong>1000 基因组</strong>数据，得到两层结果：<strong>其一</strong>，它<strong>复现了已知的尼安德特人与丹尼索瓦人混血信号</strong>，证明方法没有跑偏；<strong>其二</strong>，它在<strong>非洲人与非非洲人中同时找出未被刻画过的&quot;幽灵&quot;古人类混血</strong>——即来自<strong>既有样本库里根本没有的</strong>、已灭绝近亲的 DNA。文中还指出这种幽灵血缘<strong>在尼安德特人基因组中持续存在</strong>，暗示这些&quot;缺失的近亲&quot;曾在欧亚与非洲之间留下过交叉痕迹。这项工作的意义在于：<strong>把古人类混血研究从&quot;依赖化石&quot;解放为&quot;依赖谱系推断&quot;</strong>，让更多人群、更多未知混血事件变得可检索。</p><p><strong>跨主题关联</strong>：承接 <code>topics/paleoanthropology/index.md</code> 与 <code>topics/paleontology/index.md</code> 中&quot;古蛋白/古基因组改写家谱&quot;的主线；方法层面（<strong>从结构特征反推历史事件，而非依赖直接样本</strong>）与 <code>topics/earth-science/index.md</code> 里&quot;用代理指标反演过程&quot;的思路同构。</p><hr><h3 id="_3-直接蒸发长出单晶金属电极-二维半导体接触瓶颈的新解法" tabindex="-1">3. 直接蒸发长出单晶金属电极：二维半导体接触瓶颈的新解法 <a class="header-anchor" href="#_3-直接蒸发长出单晶金属电极-二维半导体接触瓶颈的新解法" aria-label="Permalink to &quot;3. 直接蒸发长出单晶金属电极：二维半导体接触瓶颈的新解法&quot;">​</a></h3><p><strong>原文</strong>：金属—半导体接触是二维半导体电子学的关键瓶颈；原子级分步蒸发直接在单层半导体上生长单晶金属，得到洁净界面，实现多种金属在 MoS₂ / WSe₂ 上的范德瓦耳斯外延。</p><p><strong>深度扩展</strong>：</p><p><strong>Science（2026）</strong>，<strong>21 位作者</strong>（Zhang Ying、Liu Chang、Wang Huiting、Teng Guichen、Qin Yilu 等）。二维半导体（如单层 MoS₂、WSe₂）的<strong>理论迁移率极高</strong>，但做成器件后实测常常差一个数量级——瓶颈几乎都在<strong>金属/半导体界面</strong>：常规沉积（溅射、热蒸发）在二维晶格上生成的是<strong>多晶、无序、易反应</strong>的金属层，界面态密集、费米能级钉扎严重，接触电阻居高不下。</p><p>本文的路线是<strong>不&quot;贴&quot;金属，而是&quot;长&quot;金属</strong>：用<strong>原子级、分步进行的蒸发方法</strong>直接在单层半导体表面生长<strong>单晶金属</strong>。关键机制在于选取一个特殊的<strong>生长动力学窗口</strong>——在允许金属原子表面扩散、却<strong>抑制二次成核</strong>的速率/温度条件下，原子只能<strong>横向合并（lateral coalescence）</strong>，从而与二维衬底形成<strong>范德瓦耳斯外延</strong>关系，而非无序堆积。作者在 <strong>MoS₂ 与 WSe₂</strong> 上成功外延了 <strong>铋、银、铟、金、钯</strong>等多种（涵盖低熔点与高熔点）金属，得到<strong>洁净界面</strong>，并且单晶金属层能支撑<strong>超薄导电结构</strong>。</p><p>意义有两层：对材料学，这是&quot;<strong>二维衬底上的金属外延</strong>&quot;这一此前未系统实现的组合；对器件工程，把<strong>接触从&quot;工艺妥协&quot;变成&quot;可由生长条件设计的材料问题&quot;</strong>，为二维晶体管、二维集成电路把最普遍的性能枷锁移到可控变量上传。</p><p><strong>跨主题关联</strong>：接续 <code>topics/materials/index.md</code> 中二维材料与范德瓦耳斯组装的脉络（本期同源思路亦见于 2026-10-03 的&quot;1D 纳米带编织&quot;系列）；其&quot;<strong>界面质量决定器件上限</strong>&quot;的结论与 <code>topics/physics/index.md</code> 的量子输运视角（见本期第一性原理层）互为表里。</p><hr><h3 id="_4-注入诱发地震-92-有前震-加拿大西部-77-条序列给出-红绿灯-新判据" tabindex="-1">4. 注入诱发地震 92% 有前震：加拿大西部 77 条序列给出&quot;红绿灯&quot;新判据 <a class="header-anchor" href="#_4-注入诱发地震-92-有前震-加拿大西部-77-条序列给出-红绿灯-新判据" aria-label="Permalink to &quot;4. 注入诱发地震 92% 有前震：加拿大西部 77 条序列给出&quot;红绿灯&quot;新判据&quot;">​</a></h3><p><strong>原文</strong>：前震活动是红绿灯协议（TLP）缓解注入诱发地震风险的关键考量，但 IIE 前震的孕震过程一直不清楚；本文用 2014–2024 年加拿大西部增强目录、77 条 IIE 序列统计分析 M_L ≥ 3 主震之前的前震形态。</p><p><strong>深度扩展</strong>：</p><p><strong>Science（2026）</strong>，<strong>12 位作者</strong>（Wang Bei、Kao Honn、Yu Hongyu、Jiang Yan、Lin Qiang 等）。<strong>注入诱发地震（IIE）<strong>来自油气开发、废水回注、地热等工业活动的流体注入，页岩气与地热开发密集区尤甚，因此工业现场普遍采用</strong>红绿灯协议（TLP）</strong>：地震活动一旦越过阈值就降速或停产。但 TLP 的阈值设定长期<strong>缺少对&quot;主震是否会来&quot;的前瞻判据</strong>——而<strong>前震</strong>恰恰是天然的候选信号。</p><p>作者把加拿大西部 <strong>2014–2024 年</strong>的地震记录做成<strong>增强目录</strong>（通过模板匹配等手段把可检测震级显著下推，需要说明：目录细节未在本次取证的摘要中逐条列出），从中挑出 <strong>77 条 IIE 序列</strong>——即与注入活动关联、且以<strong>局部震级 M_L ≥ 3</strong> 主震收尾的成核过程，然后统计主震之前的前震形态。</p><p>主要结果有三点：<strong>其一</strong>，<strong>92% 的 IIE 主震之前都出现过前震</strong>，说明&quot;无前震直接跳大震&quot;是少数路径；<strong>其二</strong>，<strong>前震产出率与时空格局</strong>不是随机噪声，而是<strong>流体注入强度、孕震指数（seismogenic index）、断层应力状态</strong>三者相互作用的可读产物——注入把孔隙压推向断层，有效正应力下降，破裂在成核补丁上亚临界扩展，前震是这一过程的可见外溢；<strong>其三</strong>，序列级的分析提示不同注入场景会给出不同的前震模式。这为把<strong>前震统计量</strong>纳入注入作业的实时风险阈值提供了观测依据，也提醒 TLP 的阈值不该只看&quot;当前震级是否越线&quot;。</p><p><strong>跨主题关联</strong>：丰富 <code>topics/earth-science/index.md</code> 中&quot;人为活动与地质过程耦合&quot;的案例集；与 <code>topics/energysim/index.md</code> 的能源—地质工程系统建模直接相关（注入参数是可以被工程侧调节的变量）。</p><hr><h3 id="_5-给香农信息论装上-逻辑推理-压缩极限之外的另一类基本极限" tabindex="-1">5. 给香农信息论装上&quot;逻辑推理&quot;：压缩极限之外的另一类基本极限 <a class="header-anchor" href="#_5-给香农信息论装上-逻辑推理-压缩极限之外的另一类基本极限" aria-label="Permalink to &quot;5. 给香农信息论装上&quot;逻辑推理&quot;：压缩极限之外的另一类基本极限&quot;">​</a></h3><p><strong>原文</strong>：香农信息论的奠基性思路是把消息的&quot;含义&quot;与&quot;高效传输&quot;解耦；本文提出假设发送方与接收方都具备推理能力的通信模型推广，把信息论与数理逻辑耦合起来。</p><p><strong>深度扩展</strong>：</p><p><strong>PNAS（2026）</strong>，<strong>8 位作者</strong>（Lastras Luis A.、Lenchner Jonathan、Trager Barry M.、Szpankowski Wojciech、Squillante Mark S. 等，阵容横跨工业研究院与信息论学界——机构归属未在本次取证的元数据中逐条确认，此处按作者署名列出）。</p><p><strong>问题背景</strong>：香农 1948 年的核心洞察是<strong>把&quot;含义&quot;从&quot;传输&quot;里剥出去</strong>——不管消息在说什么，只要信源是随机的，其<strong>压缩极限就是信源的熵</strong>。这条&quot;解耦&quot;让信息论成为工程学，但也意味着<strong>它从不过问接收方能否&quot;看懂&quot;</strong>。本文提出的推广是：让<strong>发送方与接收方都具有推理能力</strong>，于是&quot;要传的东西&quot;变成&quot;<strong>接收方从消息中能推出的逻辑结论</strong>&quot;，信息论与数理逻辑在此耦合。</p><p><strong>为什么重要</strong>：这是&quot;<strong>语义通信 / 推理型压缩</strong>&quot;这类问题第一次被放到<strong>可分析的基本极限框架</strong>里。它给出的定性图景是：当双方都会推理时，<strong>传输成本不再只由消息的熵决定，还由&quot;需要多少额外的逻辑信息&quot;决定</strong>——一个聪明接收方可以从少量事实推出大量结论，因此&quot;传事实&quot;与&quot;传结论&quot;是两笔不同的账。需要如实说明：本次取证的摘要<strong>未给出具体的极限表达式与数值界限</strong>，因此此处只复述其设定与定性结论，不代作断言。</p><p><strong>跨主题关联</strong>：与 <code>topics/physics/index.md</code>、<code>topics/ai-system-architecture/index.md</code> 中&quot;信息如何被表示与传递&quot;的主线呼应，也直接喂给&quot;<strong>压缩即智能</strong>&quot;这一 LLM 时代的假说（见本期第一性原理层）；是 <code>topics/cross-domain-synthesis-2026-q3.md</code> &quot;通道/表示决定上限&quot;模式的又一层地基。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-音视频-llm-的-先验支配-跨模态冲突下它们不是在组合证据-而是在念答案" tabindex="-1">6. 音视频 LLM 的&quot;先验支配&quot;：跨模态冲突下它们不是在组合证据，而是在念答案 <a class="header-anchor" href="#_6-音视频-llm-的-先验支配-跨模态冲突下它们不是在组合证据-而是在念答案" aria-label="Permalink to &quot;6. 音视频 LLM 的&quot;先验支配&quot;：跨模态冲突下它们不是在组合证据，而是在念答案&quot;">​</a></h3><p><strong>原文</strong>：把语义不兼容但时间同步的音频与视频配对，是检验音视频大模型组合泛化的好测试；VideoLLaMA 2-7B-AV 三种对齐配置都接近随机，InternVideo2 在跨模态冲突下准确率下跌 32.3%，作者将这种失效命名为&quot;先验支配&quot;。</p><p><strong>深度扩展</strong>：</p><p><strong>arXiv（2026）</strong>，第一作者 <strong>Adarsh Sudheer</strong> 等 <strong>6 人</strong>。任务设计很干净：给模型一对<strong>时间上同步、语义上互相矛盾</strong>的音频与视频（例如画面上是狗在叫、声音却在说人话），让它判断这对是否匹配。这测的不是识别能力，而是<strong>组合泛化</strong>——模型必须真正把两路证据合起来评估，而不能只依赖某一路或某个内部倾向。</p><p>失败很显著：<strong>VideoLLaMA 2-7B-AV</strong> 在 <strong>AVHBench</strong> 的精确字符串 Yes/No 子集上，<strong>三种对齐配置全部接近随机</strong>（尽管它们的输出先验偏移很大）；可直接使用的 <strong>InternVideo2</strong> 在跨模态冲突下<strong>准确率下降 32.3%</strong>，并伴随 <strong>17.3% 的指令遵循失败</strong>——注意后者说明模型不只是&quot;答错&quot;，还<strong>没有按要求作答</strong>。</p><p>作者把这种模式命名为 <strong>&quot;先验支配&quot;（prior dominance）</strong>：<strong>在深层，模型会对一个&quot;内部偏好的答案模式&quot;做出承诺，而这个承诺与冲突的输入证据只有很弱的关联</strong>。机理分析把承诺位置定在 <strong>第 25.5 ± 1 层</strong>，并发现<strong>更强的时序对齐只改变答案偏置，并不改善冲突消解</strong>——也就是说&quot;对齐得更好&quot;与&quot;会结合证据&quot;是两件事。这条结论与本期另一类工作（LongGuard 的注意力稀释、工具模型的&quot;未支撑结论&quot;）共享同一诊断：<strong>模型的行为瓶颈常常不在&quot;看不见证据&quot;，而在&quot;决策层不采用证据&quot;</strong>。</p><p><strong>跨主题关联</strong>：深化 <code>topics/ai-system-architecture/index.md</code> 中&quot;多模态融合的真实瓶颈在表示与决策层&quot;的讨论；&quot;先验压过证据&quot;与 <code>topics/intelligence-self-learning/index.md</code> 里的自我评估失败同源。</p><hr><h3 id="_7-为什么不去查一下-工具型语言模型的-未支撑结论-与可修复性" tabindex="-1">7. &quot;为什么不去查一下？&quot;：工具型语言模型的&quot;未支撑结论&quot;与可修复性 <a class="header-anchor" href="#_7-为什么不去查一下-工具型语言模型的-未支撑结论-与可修复性" aria-label="Permalink to &quot;7. &quot;为什么不去查一下？&quot;：工具型语言模型的&quot;未支撑结论&quot;与可修复性&quot;">​</a></h3><p><strong>原文</strong>：有工具可用的语言模型仍会在证据不支持的情况下下最终结论，即使一次工具调用即可消除不确定性；作者把失效拆成&quot;发生率&quot;与&quot;条件修复率&quot;两个量，并用状态精确复现的配对重放做因果检验。</p><p><strong>深度扩展</strong>：</p><p><strong>arXiv（2026）</strong>，单作者 <strong>Justin Bronder</strong>。现象的荒谬之处在于：模型<strong>手里就有工具</strong>，<strong>一次调用就能消除不确定性</strong>，<strong>指令还明确禁止假设与猜测</strong>——它依然会以一个<strong>证据不支持</strong>的&quot;已确立结论&quot;收尾。</p><p>作者的天才之处是把这件事变成<strong>可测量的两件事</strong>：<strong>发生率</strong>（模型自发做出未支撑结论的频率；关键在判定时<strong>只使用可见证据与最终结论，不用隐藏的正确答案</strong>，因此不依赖标注）和<strong>条件修复率</strong>（把缺失证据补上后，这些<strong>自然发生</strong>的错误是否被修正）。在固定的 <strong>Qwen3-32B</strong> 设置下，256 条新提示模板的 512 次首答中，有 <strong>33 次</strong>以未支撑的&quot;已确立&quot;结论收尾。</p><p>接下来是最漂亮的实验设计：<strong>对每个案例从&quot;结论产生时的状态&quot;精确复现并重放</strong>，且两种备选工具响应<strong>结构、长度完全相同，只差一个字符的响应码</strong>。结果干净利落——<strong>有效证据修复了 33/33</strong>，而<strong>携带无用信息的配对响应修复 0/33</strong>；当证据原本支持原答案时，<strong>33/33 被保留，未观察到任何损害</strong>。另一组实验中，一条<strong>自动检查规则</strong>对 64 个需要证据的案例追加 <strong>21 次证据调用</strong>，<strong>纠正了全部 10 个错误结论、保留了 11 个&quot;碰巧正确&quot;的结论、且从未把正确答案改错</strong>。在同样采样设置下 <strong>Gemma 4</strong> 呈现同类模式（原文其余数值未在本次取证的摘要片段中完整给出，此处不代作断言）。</p><p><strong>工程含义</strong>：这个失效<strong>不是能力不足，而是&quot;不检查&quot;这一行为习惯</strong>，因此<strong>无需重训即可大幅缓解</strong>——一条廉价的检查规则就能拿到&quot;零伤害的修复&quot;。这与本期 OBPE（把策略执法外置到可信边界）构成同一类解法：<strong>不要把纪律寄望于模型自身的判断，而把它做成流程结构</strong>。</p><p><strong>跨主题关联</strong>：接续 <code>topics/ai-tools/index.md</code> 中工具调用可靠性的主线，与 <code>topics/cybersecurity/index.md</code>（外置护栏）相互印证；&quot;自发行为 vs 外部检查&quot;的分离，是 <code>topics/intelligence-self-learning/index.md</code> 里自评估/自验证议题的实测证据。</p>',61)])])}const l=t(g,[["render",e]]);export{p as __pageData,l as default};
